import type {
  CssVarsObject,
  PaletteColors,
  PaletteConfig,
  PaletteRgbColors,
  RicosCustomStyles,
  RicosPalette,
  RicosTheme,
} from './../../../ricos-types/index.js';
import { THEME_COLOR_SLOT_MAP } from './../../../_shared/theme-color-token.js';

import { FALLBACK_COLOR_DEFAULT } from '../../theme-constants.js';
import { COLORS, assertWixPalette, getColorValue, isRicosPalette } from '../palettes/index.js';
import {
  adaptForeground,
  canTransformToHex,
  toCssRgb,
  toHexFormat,
  toRgbTuple,
} from '../theme-utils.js';
import { isRicosPaletteRgb } from './identifiers.js';

type StringMap = { [key: string]: string | undefined };
const RGB_VAR_COLOR_RE = /^rgb\(\s*(var\(--[^)]+\))\s*\)$/i;
const RGBA_VAR_COLOR_RE = /^rgba\(\s*(var\(--[^)]+\))\s*,\s*[^)]+\)$/i;

const isNewRicosPalette = (
  palette: RicosTheme['palette'] | RicosPalette
): palette is RicosPalette =>
  !!palette && typeof palette === 'object' && !Array.isArray(palette) && 'format' in palette;

const mapRicosPaletteToLegacyPalette = (
  palette: RicosPalette
): PaletteColors | PaletteRgbColors => {
  const mapped = {
    actionColor: palette.accent1,
    bgColor: palette.bgColor,
    textColor: palette.textColor,
    textColorLow: palette.shade1,
    disabledColor: palette.shade2,
    fallbackColor: palette.shade3,
  };
  return palette.format === 'rgbTuple' ? { ...mapped, type: 'rgb' } : mapped;
};

const colorToCss = (
  color: string | undefined,
  format: RicosPalette['format']
): string | undefined => {
  if (!color) {
    return undefined;
  }
  return format === 'rgbTuple' ? `rgb(${color})` : color;
};

const toTupleValue = (color?: string): string | undefined => {
  if (!color) {
    return undefined;
  }

  if (color === 'transparent') {
    return undefined;
  }

  if (canTransformToHex(color)) {
    return toRgbTuple(toHexFormat(color));
  }

  const rgbVarMatch = color.match(RGB_VAR_COLOR_RE);
  if (rgbVarMatch) {
    return rgbVarMatch[1];
  }

  const rgbaVarMatch = color.match(RGBA_VAR_COLOR_RE);
  if (rgbaVarMatch) {
    return rgbaVarMatch[1];
  }

  return undefined;
};

// eslint-disable-next-line @typescript-eslint/no-explicit-any
function omitUndefined(obj: Record<string, any>): Record<string, any> {
  return Object.fromEntries(
    Object.entries(obj)
      .map(([k, v]) =>
        v && typeof v === 'object' && !Array.isArray(v) ? [k, omitUndefined(v)] : [k, v]
      )
      .filter(([, v]) => v !== undefined && (typeof v !== 'object' || Object.keys(v).length > 0))
  );
}

