const createCssVars = (
  colors: PaletteColors | PaletteRgbColors,
  config?: PaletteConfig
): CssVarsObject => {
  const { contentBgColor = false, focusActionColor, settingsActionColor } = config || {};
  const isPaletteRgb = isRicosPaletteRgb(colors);

  const {
    textColor,
    bgColor: backgroundColor,
    actionColor,
    fallbackColor = isPaletteRgb ? '0, 0, 0' : FALLBACK_COLOR_DEFAULT,
    disabledColor,
    textColorLow,
    textOnActionColor,
  } = colors;

  const parseColors = (obj: StringMap): CssVarsObject =>
    Object.keys(obj).reduce((acc: StringMap, key: string) => {
      const value = obj[key];
      if (value !== undefined) {
        const normalizedTuple =
          canTransformToHex(value) && isPaletteRgb ? toRgbTuple(toHexFormat(value)) : undefined;
        const tupleValue = normalizedTuple ?? value;

        acc[key] = isPaletteRgb ? toCssRgb(tupleValue) : tupleValue;
        acc[`${key}Tuple`] = isPaletteRgb ? tupleValue : toTupleValue(tupleValue);
      }
      return acc;
    }, {});

  const parsedValues = parseColors({
    textColor,
    actionColor,
    backgroundColor,
    fallbackColor,
    disabledColor,
    textColorLow,
    settingsActionColor,
    focusActionColor,
    textOnActionColor,
  });

  const bgColorContainer =
    !contentBgColor || backgroundColor === undefined
      ? undefined
      : isPaletteRgb
        ? toCssRgb(backgroundColor)
        : backgroundColor;

  // adaptForeground not possible for RGB tuples (can be CSS vars with unknown values at build time)
  const actionColorFallback = isPaletteRgb
    ? `rgb(${fallbackColor})`
    : adaptForeground(actionColor, fallbackColor);

  const actionColorFallbackTuple = isPaletteRgb
    ? fallbackColor
    : toRgbTuple(adaptForeground(actionColor, fallbackColor));

  return {
    ...parsedValues,
    ...(actionColorFallback && { actionColorFallback }),
    ...(actionColorFallbackTuple && { actionColorFallbackTuple }),
    ...(bgColorContainer && { bgColorContainer }),
  };
};

const extractColors = (palette: RicosTheme['palette']): PaletteColors | PaletteRgbColors => {
  if (Array.isArray(palette)) {
    assertWixPalette(palette);
    return {
      actionColor: getColorValue(palette, COLORS.ACTION_COLOR),
      bgColor: getColorValue(palette, COLORS.BG_COLOR),
      textColor: getColorValue(palette, COLORS.TEXT_COLOR),
      disabledColor: getColorValue(palette, COLORS.DISABLED_COLOR),
      textColorLow: getColorValue(palette, COLORS.TEXT_COLOR_LOW),
    };
  } else if (palette && isNewRicosPalette(palette)) {
    return mapRicosPaletteToLegacyPalette(palette);
  } else if (palette && (isRicosPalette(palette) || isRicosPaletteRgb(palette))) {
    return palette;
  }
  console.error('Unrecognized Palette object. Please refer to Ricos Theme Documentation');
  return {};
};

function transformColorsToHex(colors: PaletteColors, isPaletteRgb = false): PaletteColors {
  if (isPaletteRgb) {
    return { ...colors };
  }
  return Object.fromEntries(
    Object.entries(colors).map(([key, value]) => [
      key,
      typeof value === 'string' && canTransformToHex(value) ? toHexFormat(value) : value,
    ])
  ) as PaletteColors;
}

interface PaletteStrategyResult {
  paletteVarsObject: CssVarsObject;
  colors?: PaletteColors;
}

export type ResolvedPaletteColors = Pick<
  PaletteColors,
  | 'actionColor'
  | 'bgColor'
  | 'textColor'
  | 'textColorLow'
  | 'disabledColor'
  | 'fallbackColor'
  | 'textOnActionColor'
> & {
  settingsActionColor?: string;
  focusActionColor?: string;
};

export function createPalette(
  palette?: RicosTheme['palette'],
  config?: RicosTheme['paletteConfig']
): PaletteStrategyResult {
  if (!palette) {
    return { paletteVarsObject: {} };
  }
  const extractedColors = extractColors(palette);
  const isPaletteRgb = isRicosPaletteRgb(extractedColors);
  const transformedColors = transformColorsToHex(extractedColors, isPaletteRgb);

  return {
    paletteVarsObject: createCssVars(transformedColors, config),
    colors: transformedColors,
  };
}

export function createColorPalette(
  colorPalette: RicosPalette,
  config?: PaletteConfig
): PaletteStrategyResult {
  const extractedColors = mapRicosPaletteToLegacyPalette(colorPalette);
  const isPaletteRgb = isRicosPaletteRgb(extractedColors);
  const transformedColors = transformColorsToHex(extractedColors, isPaletteRgb);
  // The toolbar / settings action color defaults to accent1, but can be
  // overridden via `settingsActionColor` when the toolbar accent needs to
  // differ from the editor's content accent color.
  const resolvedConfig =
    colorPalette.accent1 || colorPalette.settingsActionColor
      ? {
          ...config,
          settingsActionColor: colorPalette.settingsActionColor ?? colorPalette.accent1,
          focusActionColor: colorPalette.accent1,
        }
      : config;
  return {
    paletteVarsObject: createCssVars(transformedColors, resolvedConfig),
    colors: transformedColors,
  };
}

export function createThemeColorVars(colorPalette: RicosPalette): CssVarsObject {
  const isRgbTupleFormat = colorPalette.format === 'rgbTuple';
  const vars: CssVarsObject = {};

  for (const [slot, field] of Object.entries(THEME_COLOR_SLOT_MAP)) {
    const value = colorPalette[field];
    if (!value) {
      continue;
    }

    // Use pre-dashed keys so buildCssVarsObj produces --ricos-theme-color-1
    const colorKey = `theme-color-${slot}`;
    const tupleKey = `theme-color-${slot}-tuple`;

    if (isRgbTupleFormat) {
      vars[colorKey] = toCssRgb(value);
      vars[tupleKey] = value;
    } else {
      vars[colorKey] = value;
      vars[tupleKey] = toTupleValue(value);
    }
  }

  return vars;
}

/**
 * Derive theme-color CSS vars from legacy PaletteColors.
 * Legacy palettes lack accent2–accent4, so $theme-color-4..6 will remain
 * unresolved (render as empty/transparent). Content targeting all nine slots
 * should use `theme.colorPalette` (RicosPalette) instead.
 */
export function createThemeColorVarsFromLegacyPalette(colors: PaletteColors): CssVarsObject {
  const LEGACY_SLOT_MAP: [string, string | undefined][] = [
    ['1', colors.bgColor],
    ['2', colors.textColor],
    ['3', colors.actionColor],
    ['7', colors.textColorLow],
    ['8', colors.disabledColor],
    ['9', colors.fallbackColor],
  ];
  const vars: CssVarsObject = {};
  for (const [slot, value] of LEGACY_SLOT_MAP) {
    if (!value || !canTransformToHex(value)) {
      continue;
    }
    const hex = toHexFormat(value);
    vars[`theme-color-${slot}`] = hex;
    vars[`theme-color-${slot}-tuple`] = toRgbTuple(hex);
  }
  return vars;
}

export function getResolvedPaletteColors(
  palette?: RicosTheme['palette'],
  config?: RicosTheme['paletteConfig']
): ResolvedPaletteColors {
  const { paletteVarsObject } = createPalette(palette, config);
  return extractResolvedColors(paletteVarsObject);
}

export function getResolvedColorPaletteColors(
  colorPalette: RicosPalette,
  config?: PaletteConfig
): ResolvedPaletteColors {
  const { paletteVarsObject } = createColorPalette(colorPalette, config);
  return extractResolvedColors(paletteVarsObject);
}

function extractResolvedColors(paletteVarsObject: CssVarsObject): ResolvedPaletteColors {
  const getColor = (key: string) => {
    const value = paletteVarsObject[key];
    return typeof value === 'string' ? value : undefined;
  };
  return {
    actionColor: getColor('actionColor'),
    bgColor: getColor('backgroundColor'),
    textColor: getColor('textColor'),
    textColorLow: getColor('textColorLow'),
    disabledColor: getColor('disabledColor'),
    fallbackColor: getColor('fallbackColor'),
    textOnActionColor: getColor('textOnActionColor'),
    settingsActionColor: getColor('settingsActionColor'),
    focusActionColor: getColor('focusActionColor'),
  };
}
